import{_ as a,o as e,c as i,ae as p}from"./chunks/framework.dxkK2hvP.js";const c=JSON.parse('{"title":"第四章 ZooKeeper 集群部署","description":"介绍三节点环境下 ZooKeeper 的安装、配置、数据目录规划、节点编号设置以及集群启动验证流程。","frontmatter":{"title":"第四章 ZooKeeper 集群部署","description":"介绍三节点环境下 ZooKeeper 的安装、配置、数据目录规划、节点编号设置以及集群启动验证流程。","categories":["Linux 分布式集群"],"outline":[2,3],"date":"2026-03-13T00:00:00.000Z","recommend":4,"tags":["运维","分布式","Linux","Hadoop","ZooKeeper"],"head":[["meta",{"name":"keywords","content":"Linux企业级运维, 分布式, Linux, ZooKeeper, 架构, Hadoop, 大数据"}]],"cover":"https://cdn.imufeng.cn/mblog/202411161444264.png"},"headers":[],"relativePath":"training/linux/hadoop-cluster/zookeeper-install.md","filePath":"training/linux/hadoop-cluster/zookeeper-install.md","lastUpdated":1774319582000}'),n={name:"training/linux/hadoop-cluster/zookeeper-install.md"};function t(l,s,h,o,d,r){return e(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1773360000000"},[...s[0]||(s[0]=[p(`<h1 id="第四章-zookeeper-集群部署" tabindex="-1">第四章 ZooKeeper 集群部署 <a class="header-anchor" href="#第四章-zookeeper-集群部署" aria-label="Permalink to &quot;第四章 ZooKeeper 集群部署&quot;">​</a></h1><p>ZooKeeper 是 Apache 基金会维护的分布式协调服务，常用于配置管理、命名服务、分布式锁和 Leader 选举。在 Hadoop 生态中，它是很多组件实现协调与一致性的重要基础设施。</p><h2 id="一、zookeeper-简介" tabindex="-1">一、ZooKeeper 简介 <a class="header-anchor" href="#一、zookeeper-简介" aria-label="Permalink to &quot;一、ZooKeeper 简介&quot;">​</a></h2><p>ZooKeeper 通过一套轻量但可靠的协调机制，帮助分布式系统解决以下问题：</p><ul><li>节点状态感知</li><li>配置集中管理</li><li>分布式锁</li><li>服务注册与发现</li><li>Leader 选举</li></ul><p>ZooKeeper 内部维护了一棵类似文件系统的树形结构，每个节点称为 <code>ZNode</code>。它支持持久节点、临时节点和顺序节点，并通过 Watch 机制实现事件通知。</p><h2 id="二、下载安装-zookeeper" tabindex="-1">二、下载安装 ZooKeeper <a class="header-anchor" href="#二、下载安装-zookeeper" aria-label="Permalink to &quot;二、下载安装 ZooKeeper&quot;">​</a></h2><p>可前往官方发布页选择版本。这里以 <code>ZooKeeper 3.9.5</code> 为例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.apache.org/dyn/closer.lua/zookeeper/zookeeper-3.9.5/apache-zookeeper-3.9.5-bin.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zxf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache-zookeeper-3.9.5-bin.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache-zookeeper-3.9.5-bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zookeeper</span></span></code></pre></div><p>安装完成后目录大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bin/</span></span>
<span class="line"><span>conf/</span></span>
<span class="line"><span>docs/</span></span>
<span class="line"><span>lib/</span></span>
<span class="line"><span>LICENSE.txt</span></span>
<span class="line"><span>NOTICE.txt</span></span>
<span class="line"><span>README.md</span></span>
<span class="line"><span>README_packaging.md</span></span></code></pre></div><h2 id="三、配置-zookeeper" tabindex="-1">三、配置 ZooKeeper <a class="header-anchor" href="#三、配置-zookeeper" aria-label="Permalink to &quot;三、配置 ZooKeeper&quot;">​</a></h2><p>ZooKeeper 的核心配置文件为 <code>conf/zoo.cfg</code>。可以从示例文件复制：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/zookeeper/conf/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zoo_sample.cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zoo.cfg</span></span></code></pre></div><p>编辑后的 <code>zoo.cfg</code> 可参考如下内容：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">tickTime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">initLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">syncLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">dataDir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/data/zookeeper</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clientPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2181</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=master.local:2888:3888</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=node01.local:2888:3888</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=node02.local:2888:3888</span></span></code></pre></div><p>参数说明：</p><ul><li><code>tickTime</code>：基础时间单元。</li><li><code>initLimit</code>：Follower 与 Leader 初始连接允许的最大心跳数。</li><li><code>syncLimit</code>：Follower 与 Leader 请求/应答允许的最大心跳数。</li><li><code>dataDir</code>：ZooKeeper 数据目录。</li><li><code>clientPort</code>：客户端连接端口，默认 <code>2181</code>。</li><li><code>server.x</code>：集群节点定义，格式为 <code>主机名:同步端口:选举端口</code>。</li></ul><h2 id="四、配置节点编号-myid" tabindex="-1">四、配置节点编号 <code>myid</code> <a class="header-anchor" href="#四、配置节点编号-myid" aria-label="Permalink to &quot;四、配置节点编号 \`myid\`&quot;">​</a></h2><p>每个 ZooKeeper 节点都需要在 <code>dataDir</code> 目录下写入一个 <code>myid</code> 文件，用于标识自己的服务器编号。</p><p>先创建数据目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/zookeeper</span></span></code></pre></div><p>然后分别在三台机器写入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># master.local</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/zookeeper/myid</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># node01.local</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;2&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/zookeeper/myid</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># node02.local</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;3&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/zookeeper/myid</span></span></code></pre></div><p>这里的数字必须与 <code>zoo.cfg</code> 中 <code>server.x</code> 的编号一一对应。</p><h2 id="五、配置环境变量" tabindex="-1">五、配置环境变量 <a class="header-anchor" href="#五、配置环境变量" aria-label="Permalink to &quot;五、配置环境变量&quot;">​</a></h2><p>为了方便执行命令，可以将 ZooKeeper 的 <code>bin</code> 目录加入环境变量。</p><p>如果使用 <code>bash</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ZOOKEEPER_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/usr/local/zookeeper</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:$ZOOKEEPER_HOME/bin</span></span></code></pre></div><p>如果使用 <code>fish</code>：</p><div class="language-fish vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">fish</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">fish_add_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /usr/local/zookeeper/bin</span></span></code></pre></div><p>配置完成后重新加载 shell。</p><h2 id="六、同步到其他节点" tabindex="-1">六、同步到其他节点 <a class="header-anchor" href="#六、同步到其他节点" aria-label="Permalink to &quot;六、同步到其他节点&quot;">​</a></h2><p>建议先在 Master 节点完成安装和配置，再统一同步至其他节点。</p><p>例如使用 <code>ms</code> 脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/zookeeper/</span></span></code></pre></div><p>同步后记得分别检查：</p><ul><li><code>/usr/local/zookeeper/conf/zoo.cfg</code> 是否一致。</li><li><code>/data/zookeeper/myid</code> 是否为当前节点自己的编号。</li></ul><p>注意：<code>myid</code> 文件不能直接整目录覆盖，否则三个节点可能拿到相同编号。</p><h2 id="七、启动集群" tabindex="-1">七、启动集群 <a class="header-anchor" href="#七、启动集群" aria-label="Permalink to &quot;七、启动集群&quot;">​</a></h2><p>ZooKeeper 通过 <code>zkServer.sh</code> 管理服务。</p><h3 id="_7-1-启动" tabindex="-1">7.1 启动 <a class="header-anchor" href="#_7-1-启动" aria-label="Permalink to &quot;7.1 启动&quot;">​</a></h3><p>分别在三台服务器执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkServer.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="_7-2-查看状态" tabindex="-1">7.2 查看状态 <a class="header-anchor" href="#_7-2-查看状态" aria-label="Permalink to &quot;7.2 查看状态&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkServer.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>在三节点集群中，正常情况下会选举出：</p><ul><li>1 个 <code>leader</code></li><li>2 个 <code>follower</code></li></ul><h3 id="_7-3-停止与重启" tabindex="-1">7.3 停止与重启 <a class="header-anchor" href="#_7-3-停止与重启" aria-label="Permalink to &quot;7.3 停止与重启&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkServer.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkServer.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><h2 id="八、验证集群是否正常" tabindex="-1">八、验证集群是否正常 <a class="header-anchor" href="#八、验证集群是否正常" aria-label="Permalink to &quot;八、验证集群是否正常&quot;">​</a></h2><p>可以在任意节点执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkServer.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>也可以通过客户端连接：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zkCli.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master.local:2181</span></span></code></pre></div><p>连接成功后，可简单执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls /</span></span></code></pre></div><p>如果能正常返回根节点列表，说明 ZooKeeper 服务基本正常。</p><h2 id="九、本章小结" tabindex="-1">九、本章小结 <a class="header-anchor" href="#九、本章小结" aria-label="Permalink to &quot;九、本章小结&quot;">​</a></h2><p>完成本章后，你应当已经得到一套三节点的 ZooKeeper 集群。后续部署 Hive 等组件时，就可以把 ZooKeeper 作为重要的协调基础设施接入。</p><h2 id="参考内容" tabindex="-1">参考内容 <a class="header-anchor" href="#参考内容" aria-label="Permalink to &quot;参考内容&quot;">​</a></h2><ul><li><a href="https://zookeeper.apache.org/" target="_blank" rel="noreferrer">Apache ZooKeeper</a></li><li><a href="https://zookeeper.apache.org/releases.html" target="_blank" rel="noreferrer">Apache ZooKeeper Releases</a></li><li><a href="https://zookeeper.apache.org/doc/current/zookeeperAdmin.html" target="_blank" rel="noreferrer">ZooKeeper Administrator&#39;s Guide</a></li></ul>`,62)])])}const g=a(n,[["render",t]]);export{c as __pageData,g as default};
